"""Fine-tune the vocoder (Vocos or BigVGAN-v2) on mels generated by the trained TTS model ("GTA" fine-tuning).

The frozen TTS model produces mels for training utterances under the *ground-truth* alignment
(teacher-forced durations), so every generated frame lines up with the recorded waveform. The
vocoder is then trained to turn the model's (smoother) mels into the real audio with its original
GAN objective:

- ``vocos``: fresh multi-period and multi-resolution discriminators (none were released), hinge
  loss, feature matching and an L1 log-mel loss, after a discriminator warm-up.
- ``bigvgan``: resumes NVIDIA's released generator *and* discriminators (MPD + multi-scale sub-band
  CQT) with their AdamW states, as the official recipe does; LSGAN, feature matching and the
  multi-scale mel L1 (x15), at the learning rate where the released schedule ended.
"""

from __future__ import annotations

import argparse
import itertools
import time
from contextlib import nullcontext
from pathlib import Path

import torch
from torch.utils.data import DataLoader

from .alignment import sequence_mask
from .audio import HOP_LENGTH, SAMPLE_RATE
from .config import load_config, save_config
from .data import BucketBatchSampler, MelDataset, collate
from .models import bigvgan_disc as bd
from .models.text_encoder import align, token_pitch
from .utils import count_params, infinite, save_checkpoint, seed_everything
from .vocoder import BIGVGAN_REPO, build_bigvgan, build_vocos


def add_args(p: argparse.ArgumentParser) -> None:
    p.add_argument("--config", default="configs/vocoder.yaml")
    p.add_argument("--workdir", default="runs/vocoder")
    p.add_argument("overrides", nargs="*", help="config overrides, e.g. train.steps=1000")


@torch.no_grad()
def gta_mels(tts, batch: dict, temperature: float, device, cfg_scale: float = 1.0, steps: int | None = None,
             generator: torch.Generator | None = None) -> torch.Tensor:
    """Teacher-forced (ground-truth alignment) generated mels ``[B, n_mels, T]`` (normalised).

    Pitch-conditioned models use the ground-truth pitch from ``batch["f0"]``, or the predicted pitch without it."""
    text, text_len = batch["text"].to(device), batch["text_len"].to(device)
    y, y_len, spk = batch["mel"].to(device), batch["mel_len"].to(device), batch["spk"].to(device)
    y_mask = sequence_mask(y_len, y.shape[-1])
    h, mu, _, x_mask = tts.encoder(text, text_len, spk)
    attn, _ = align(mu, x_mask, y, y_mask[:, None].float())
    if tts.pitch_enabled:
        lf0_mean, lf0_std = tts.lf0_stats.tolist()
        pitch = token_pitch(batch["f0"].to(device), attn, lf0_mean, lf0_std) if "f0" in batch else None
        h, _ = tts.pitch_condition(h, x_mask, spk, pitch)
    cond = tts.frame_condition(h, mu, attn)
    z = torch.randn(y.shape[0], y.shape[1], y.shape[-1], device=device, generator=generator) * temperature
    alpha = torch.full((y.shape[0],), float(cfg_scale), device=device)
    steps = tts.generator.num_steps if steps is None else steps
    return tts.rollout(z, cond, spk, alpha, steps, generator=generator, mask=y_mask) * y_mask[:, None]


def segment_samples(frames: int, backend: str = "vocos") -> int:
    """Waveform samples produced from ``frames`` mel frames. Vocos (centred STFT, ISTFT head): frame ``i`` is centred
    on sample ``i * hop``, so ``F`` frames <-> ``(F - 1) * hop`` samples. BigVGAN (reflect-padded uncentred STFT,
    256x upsampler): frame ``i`` is centred on ``i * hop + hop / 2``, so ``F`` frames <-> ``F * hop`` samples."""
    return (frames - 1) * HOP_LENGTH if backend == "vocos" else frames * HOP_LENGTH


def random_segments(mel: torch.Tensor, audio: torch.Tensor, mel_len: torch.Tensor, frames: int,
                    backend: str = "vocos"):
    """Aligned random windows: mel frames ``[s, s + frames)`` <-> samples ``[s * hop, s * hop + n)``."""
    B = mel.shape[0]
    starts = (torch.rand(B) * (mel_len.cpu() - frames + 1).clamp_min(1).float()).long()
    n = segment_samples(frames, backend)
    m = torch.stack([mel[i, :, s: s + frames] for i, s in enumerate(starts.tolist())])
    a = torch.stack([audio[i, s * HOP_LENGTH: s * HOP_LENGTH + n] for i, s in enumerate(starts.tolist())])
    return m, a


class VocosGAN:
    """Vocos generator + fresh MPD / MRD: hinge + feature matching + 45 x log-mel L1 (the Vocos recipe)."""

    backend, export_name = "vocos", "vocos_ft.pt"

    def __init__(self, cfg, device):
        from vocos.discriminators import MultiPeriodDiscriminator, MultiResolutionDiscriminator
        from vocos.loss import DiscriminatorLoss, FeatureMatchingLoss, GeneratorLoss, MelSpecReconstructionLoss

        self.cfg, tc = cfg, cfg.train
        self.vocos = build_vocos(cfg.vocoder.init).to(device).train()
        self.mpd, self.mrd = MultiPeriodDiscriminator().to(device), MultiResolutionDiscriminator().to(device)
        self.gen_params = list(self.vocos.backbone.parameters()) + list(self.vocos.head.parameters())
        self.opt_g = torch.optim.AdamW(self.gen_params, lr=tc.lr, betas=(0.8, 0.9))
        self.opt_d = torch.optim.AdamW(list(self.mpd.parameters()) + list(self.mrd.parameters()), lr=tc.lr,
                                       betas=(0.8, 0.9))
        self.disc_loss, self.gen_loss, self.fm_loss = DiscriminatorLoss(), GeneratorLoss(), FeatureMatchingLoss()
        self.mel_loss = MelSpecReconstructionLoss(sample_rate=SAMPLE_RATE).to(device)
        self.n_gen, self.n_disc = count_params(self.vocos), count_params(self.mpd) + count_params(self.mrd)

    def generate(self, mel: torch.Tensor) -> torch.Tensor:  # Vocos.decode runs under inference_mode
        return self.vocos.head(self.vocos.backbone(mel))

    def step(self, mel: torch.Tensor, audio: torch.Tensor, step: int) -> dict:
        tc = self.cfg.train
        with torch.no_grad():
            audio_hat = self.generate(mel)
        r_mp, g_mp, _, _ = self.mpd(y=audio, y_hat=audio_hat)
        r_mr, g_mr, _, _ = self.mrd(y=audio, y_hat=audio_hat)
        l_mp, l_mp_r, _ = self.disc_loss(disc_real_outputs=r_mp, disc_generated_outputs=g_mp)
        l_mr, l_mr_r, _ = self.disc_loss(disc_real_outputs=r_mr, disc_generated_outputs=g_mr)
        l_d = l_mp / len(l_mp_r) + tc.mrd_loss_coeff * l_mr / len(l_mr_r)
        self.opt_d.zero_grad(set_to_none=True)
        l_d.backward()
        self.opt_d.step()

        metrics = {"disc": l_d.item()}
        if step >= tc.disc_warmup_steps:  # generator frozen while the fresh discriminators warm up
            audio_hat = self.generate(mel)
            _, g_mp, f_r_mp, f_g_mp = self.mpd(y=audio, y_hat=audio_hat)
            _, g_mr, f_r_mr, f_g_mr = self.mrd(y=audio, y_hat=audio_hat)
            lg_mp, lst_mp = self.gen_loss(disc_outputs=g_mp)
            lg_mr, lst_mr = self.gen_loss(disc_outputs=g_mr)
            l_fm = self.fm_loss(fmap_r=f_r_mp, fmap_g=f_g_mp) / len(f_r_mp) + \
                tc.mrd_loss_coeff * self.fm_loss(fmap_r=f_r_mr, fmap_g=f_g_mr) / len(f_r_mr)
            l_mel = self.mel_loss(audio_hat, audio)
            l_g = lg_mp / len(lst_mp) + tc.mrd_loss_coeff * lg_mr / len(lst_mr) + l_fm + tc.mel_loss_coeff * l_mel
            self.opt_g.zero_grad(set_to_none=True)
            l_g.backward()
            torch.nn.utils.clip_grad_norm_(self.gen_params, tc.grad_clip)
            self.opt_g.step()
            metrics.update(gen=l_g.item(), mel=l_mel.item(), fm=l_fm.item())
        return metrics

    def state_dict(self) -> dict:
        return dict(vocos=self.vocos.state_dict(), mpd=self.mpd.state_dict(), mrd=self.mrd.state_dict(),
                    opt_g=self.opt_g.state_dict(), opt_d=self.opt_d.state_dict())

    def load_state_dict(self, ck: dict) -> None:
        for k in ("vocos", "mpd", "mrd", "opt_g", "opt_d"):
            getattr(self, k).load_state_dict(ck[k])

    def export(self, path: Path, step: int) -> None:
        save_checkpoint(path, vocos=self.vocos.state_dict(), init=self.cfg.vocoder.init, step=step)


class BigVGANGAN:
    """BigVGAN-v2 generator (weight norm kept for training) + MPD + multi-scale sub-band CQT discriminator, LSGAN +
    feature matching + multi-scale mel L1, AdamW (0.8, 0.99), per-step exponential LR decay (official ``train.py``)."""

    backend, export_name = "bigvgan", "bigvgan_ft.pt"

    def __init__(self, cfg, device):
        self.cfg, vc, tc = cfg, cfg.vocoder, cfg.train
        self.repo = vc.get("repo", BIGVGAN_REPO)
        self.gen = build_bigvgan(self.repo, vc.get("hparams"), pretrained=vc.get("pretrained", True)).to(device)
        if tc.get("compile", False):  # fuse the anti-aliased snake activations: less memory, fewer kernel launches
            for m in self.gen.modules():
                if type(m).__name__ == "Activation1d":
                    m.compile()
        h = self.gen.h
        self.mpd = bd.MultiPeriodDiscriminator(h).to(device)
        self.mrd = bd.MultiScaleSubbandCQTDiscriminator(h).to(device)  # "mrd" as in the released checkpoint
        betas = tuple(tc.get("betas", (h["adam_b1"], h["adam_b2"])))
        self.opt_g = torch.optim.AdamW(self.gen.parameters(), tc.lr, betas=betas)
        # same parameter order as the reference (CQT-D first), so its optimizer state can be loaded
        self.d_params = list(itertools.chain(self.mrd.parameters(), self.mpd.parameters()))
        self.opt_d = torch.optim.AdamW(self.d_params, tc.lr, betas=betas)
        if vc.get("pretrained_discriminators", True):
            self._load_released(vc.get("pretrained_optimizer", True))
        self.sched_g, self.sched_d = (torch.optim.lr_scheduler.ExponentialLR(o, tc.get("lr_decay", 1.0))
                                      for o in (self.opt_g, self.opt_d))
        self.mel_loss = bd.MultiScaleMelLoss(SAMPLE_RATE).to(device)
        bf16 = tc.get("bf16_disc", False)
        self.amp = lambda: torch.autocast(device.split(":")[0], torch.bfloat16) if bf16 else nullcontext()
        self.n_gen, self.n_disc = count_params(self.gen), count_params(self.mpd) + count_params(self.mrd)

    def _load_released(self, optimizer: bool) -> None:
        from huggingface_hub import hf_hub_download

        ck = torch.load(hf_hub_download(self.repo, "bigvgan_discriminator_optimizer.pt"), map_location="cpu",
                        weights_only=False)
        self.mpd.load_state_dict(ck["mpd"])
        self.mrd.load_state_dict(ck["mrd"])
        if optimizer:  # AdamW moments of the 5M-step run; the learning rate is ours
            for opt, key in ((self.opt_g, "optim_g"), (self.opt_d, "optim_d")):
                hp = {k: v for k, v in opt.param_groups[0].items() if k != "params"}
                opt.load_state_dict(ck[key])
                for g in opt.param_groups:
                    g.pop("initial_lr", None)
                    g.update(hp)
                for p in opt.param_groups[0]["params"]:
                    assert opt.state[p]["exp_avg"].shape == p.shape, "optimizer state does not match the model"
        print(f"loaded the released discriminators{' and optimizer states' if optimizer else ''} "
              f"(step {ck['steps']})", flush=True)

    def generate(self, mel: torch.Tensor) -> torch.Tensor:
        """Full utterances (samples): eager, so variable lengths do not trigger recompilation."""
        with torch.compiler.set_stance("force_eager") if self.cfg.train.get("compile") else nullcontext():
            return self.gen(mel)[:, 0]

    def step(self, mel: torch.Tensor, audio: torch.Tensor, step: int) -> dict:
        tc = self.cfg.train
        y, y_hat = audio[:, None], self.gen(mel)  # generator in fp32: snake activations need the precision
        with self.amp():
            r_p, g_p, _, _ = self.mpd(y, y_hat.detach())
            r_c, g_c, _, _ = self.mrd(y, y_hat.detach())
        l_d_p, l_d_c = bd.discriminator_loss(r_p, g_p), bd.discriminator_loss(r_c, g_c)
        self.opt_d.zero_grad(set_to_none=True)
        (l_d_p + l_d_c).backward()
        gn_p = torch.nn.utils.clip_grad_norm_(self.mpd.parameters(), tc.grad_clip)
        gn_c = torch.nn.utils.clip_grad_norm_(self.mrd.parameters(), tc.grad_clip)
        self.opt_d.step()

        metrics = {"disc_mpd": l_d_p.item(), "disc_cqtd": l_d_c.item(), "grad_mpd": gn_p.item(),
                   "grad_cqtd": gn_c.item()}
        if step >= tc.disc_warmup_steps:
            l_mel = self.mel_loss(y_hat, y)
            with self.amp():
                _, g_p, f_r_p, f_g_p = self.mpd(y, y_hat)
                _, g_c, f_r_c, f_g_c = self.mrd(y, y_hat)
            l_adv = bd.generator_loss(g_p) + bd.generator_loss(g_c)
            l_fm = bd.feature_loss(f_r_p, f_g_p) + bd.feature_loss(f_r_c, f_g_c)
            l_g = l_adv + l_fm + tc.mel_loss_coeff * l_mel
            self.opt_g.zero_grad(set_to_none=True)
            l_g.backward()
            gn_g = torch.nn.utils.clip_grad_norm_(self.gen.parameters(), tc.grad_clip)
            self.opt_g.step()
            metrics.update(gen=l_g.item(), adv=l_adv.item(), fm=l_fm.item(), mel=l_mel.item(), grad_gen=gn_g.item())
        self.sched_g.step()
        self.sched_d.step()
        metrics["lr"] = self.sched_g.get_last_lr()[0]
        return metrics

    def state_dict(self) -> dict:
        return dict(generator=self.gen.state_dict(), mpd=self.mpd.state_dict(), mrd=self.mrd.state_dict(),
                    opt_g=self.opt_g.state_dict(), opt_d=self.opt_d.state_dict(), sched_g=self.sched_g.state_dict(),
                    sched_d=self.sched_d.state_dict())

    def load_state_dict(self, ck: dict) -> None:
        self.gen.load_state_dict(ck["generator"])
        for k in ("mpd", "mrd", "opt_g", "opt_d", "sched_g", "sched_d"):
            getattr(self, k).load_state_dict(ck[k])

    def export(self, path: Path, step: int) -> None:
        """Same layout as the released ``bigvgan_generator.pt`` (weight norm kept) + the hparams to rebuild it."""
        h = {k: v for k, v in self.gen.h.items() if k != "use_cuda_kernel"}
        save_checkpoint(path, generator=self.gen.state_dict(), hparams=h, repo=self.repo, step=step)


@torch.no_grad()
def log_samples(gan, tts, batch: dict, stats: dict, tc, writer, step: int, device) -> None:
    """Full validation utterances: the vocoder on GTA mels and on recorded mels, plus the real audio."""
    gta = gta_mels(tts, batch, tc.gta_temperature, device) * stats["std"] + stats["mean"]
    rec = batch["mel"].to(device) * stats["std"] + stats["mean"]
    for i, n in enumerate(batch["mel_len"].tolist()):
        for name, mel in (("gta", gta), ("recorded_mel", rec)):
            wav = gan.generate(mel[i: i + 1, :, :n])[0].clamp(-1, 1).float().cpu()
            writer.add_audio(f"{name}/{i}", wav, step, sample_rate=SAMPLE_RATE)
        writer.add_audio(f"real/{i}", batch["audio"][i, : segment_samples(n, gan.backend)], step,
                         sample_rate=SAMPLE_RATE)


def run(args) -> None:
    from torch.utils.tensorboard import SummaryWriter

    from .train import load_tts

    cfg = load_config(args.config, args.overrides)
    work = Path(args.workdir)
    work.mkdir(parents=True, exist_ok=True)
    save_config(cfg, work / "config.yaml")
    tc = cfg.train
    seed_everything(tc.seed)
    device = "cuda" if torch.cuda.is_available() and not tc.get("cpu", False) else "cpu"

    tts, tts_cfg, stats = load_tts(cfg.tts.path, device)
    backend = stats.get("backend", "vocos")
    if cfg.vocoder.get("backend", backend) != backend:
        raise ValueError(f"config asks for a {cfg.vocoder.backend} vocoder but the TTS model was trained on "
                         f"{backend} mels (`prepare --backend`)")
    tts.requires_grad_(False)
    d = cfg.data
    ds = MelDataset(d.root, "train", min_quality=d.min_quality, min_frames=tc.segment_frames, max_frames=d.max_frames,
                    with_audio=True, with_f0=tts.pitch_enabled, filters=d.get("filters"))
    sampler = BucketBatchSampler([ds.frames(i) for i in range(len(ds))], max_frames=tc.batch_frames,
                                 max_batch=tc.batch_size, seed=tc.seed)
    loader = DataLoader(ds, batch_sampler=sampler, collate_fn=collate, num_workers=tc.num_workers,
                        pin_memory=True, persistent_workers=tc.num_workers > 0)

    gan = (BigVGANGAN if backend == "bigvgan" else VocosGAN)(cfg, device)
    print(f"{backend} vocoder {gan.n_gen:.1f}M, discriminators {gan.n_disc:.1f}M, {len(ds)} utterances", flush=True)
    writer = SummaryWriter(work / "tb")
    samples = None
    if tc.get("sample_every", 0) > 0:
        val = MelDataset(d.root, "val", min_frames=tc.segment_frames, max_frames=d.max_frames, with_audio=True,
                         with_f0=tts.pitch_enabled)
        val = val if len(val) else ds
        samples = collate([val[i] for i in range(min(tc.get("num_samples", 2), len(val)))])

    step = 0
    if (work / "last.pt").exists():
        ck = torch.load(work / "last.pt", map_location="cpu", weights_only=False)
        gan.load_state_dict(ck)
        step = ck["step"]
        sampler.epoch = ck.get("epoch", 0)
        print(f"resumed from step {step}", flush=True)

    it = infinite(loader)
    t0, agg = time.time(), {}
    while step < tc.steps:
        batch = next(it)
        use_gta = torch.rand(()) < tc.gta_prob
        mel = gta_mels(tts, batch, tc.gta_temperature, device) if use_gta else batch["mel"].to(device)
        mel = mel * stats["std"] + stats["mean"]  # back to log-mel, the vocoder's input
        mel, audio = random_segments(mel, batch["audio"].to(device), batch["mel_len"], tc.segment_frames, backend)
        with torch.backends.cudnn.flags(enabled=True, benchmark=True):  # fixed segment shapes: faster convolutions
            metrics = gan.step(mel, audio, step)
        step += 1
        for k, v in metrics.items():
            agg[k] = agg.get(k, 0.0) + v
        if step % tc.log_every == 0:
            n = tc.log_every
            for k, v in agg.items():
                writer.add_scalar(f"vocoder/{k}", v / n, step)
            rate = n / (time.time() - t0)
            mem = f", {torch.cuda.max_memory_allocated() / 2**30:.1f} GB" if device == "cuda" else ""
            print(f"step {step} " + " ".join(f"{k}={v / n:.4g}" for k, v in agg.items()) + f" ({rate:.2f} it/s{mem})",
                  flush=True)
            t0, agg = time.time(), {}
        if samples is not None and step % tc.sample_every == 0:
            log_samples(gan, tts, samples, stats, tc, writer, step, device)
        if step % tc.save_every == 0 or step == tc.steps:
            save_checkpoint(work / "last.pt", step=step, epoch=sampler.epoch, **gan.state_dict())
            gan.export(work / gan.export_name, step)
    print(f"done: {work / gan.export_name}", flush=True)
